function save(){C.enableHomaRules(state);C.syncV2(state);C.validateState(state);if(storageIssue)throw new Error(storageIssue);state.updatedAt=new Date(Math.max(Date.now(),(Date.parse(state.updatedAt)||0)+1)).toISOString();const json=JSON.stringify(state);if(lastSavedJSON)localStorage.setItem(BACKUP,lastSavedJSON);localStorage.setItem(KEY,json);lastSavedJSON=json;window.FPAccess?.queueSave?.(C.copy(state));}
function transact(fn,success=null){
 const before=C.copy(state);let external=null;
 try{
  if(storageIssue)throw new Error(storageIssue);
  const disk=localStorage.getItem(KEY);if(disk!==lastSavedJSON){if(!disk)throw new Error('Los datos de esta cuenta han cambiado. Vuelve a abrirla.');external=C.validateState(JSON.parse(disk));}
  fn(state);for(const item of state.shopping)if(!item.listId)item.listId=typeof web5!=='undefined'?web5.shoppingList:'groceries';
  if(external){const result=window.HomaSync.merge(before,state,external);if(!result.ok){state=external;lastSavedJSON=disk;render();throw new Error('Otra pestaña ha cambiado el mismo dato. No se ha sobrescrito. Revisa y repite: '+result.conflicts.slice(0,2).join(', '));}state=C.validateState(result.value);lastSavedJSON=disk;}
  if(!state.demo&&JSON.stringify(before)!==JSON.stringify(state)){state.houseLog.unshift({id:C.uid('log'),at:new Date().toISOString(),action:(success||'Datos actualizados')+' - '+(actor.memberId?member(actor.memberId).name:'Adulto')});state.houseLog.length=Math.min(500,state.houseLog.length);}
  save();
 }catch(e){if(external){state=external;lastSavedJSON=localStorage.getItem(KEY);}else state=before;toast(e.message||'No se ha podido guardar. Exporta una copia de seguridad.',true);return false;}
 render();if(success)toast(success);return true;
}

try{const changed=C.rollover(state);if(!lastSavedJSON||changed)save();}catch(e){if(!storageIssue)storageIssue='No se ha podido guardar en este navegador. Exporta una copia antes de salir.';}
function needAdult(){if(!isAdult()){toast('Esta acción necesita el modo adulto.',true);return false;}return true;}
function toast(message,error=false,undo=null){const box=document.createElement('div');box.className='toast'+(error?' error':'');box.innerHTML=icon(error?'info':'check')+`<span>${esc(message)}</span>`;if(undo){const b=document.createElement('button');b.type='button';b.className='toast-undo';b.textContent='Deshacer';b.onclick=()=>{undo();box.remove();};box.appendChild(b);}$('#toasts').appendChild(box);while($('#toasts').children.length>3)$('#toasts').firstElementChild.remove();setTimeout(()=>box.remove(),error?7500:4800);}
function celebrate(message){toast(message);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.createElement('div');el.className='celebration';el.setAttribute('aria-hidden','true');for(let i=0;i<54;i++){const p=document.createElement('i');p.className='confetti';p.style.cssText=`left:${Math.random()*100}%;--confetti-color:${['#b39bd7','#f2c881','#86baa4','#e9b5c2','#a7bfdf'][i%5]};--drift:${Math.round(Math.random()*200-100)}px;animation-delay:${Math.random()*.6}s;transform:rotate(${Math.random()*180}deg)`;el.appendChild(p);}document.body.appendChild(el);setTimeout(()=>el.remove(),3400);}
