const selectOptions=(items,selected)=>items.map(x=>{const value=typeof x==='object'?x.value:x,label=typeof x==='object'?x.label:x;return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;}).join('');
