 if(ui.kitchenActive&&ui.view!=='kitchen'&&!$('#v3-tablet-back')){const main=$('main');if(main){const b=document.createElement('button');b.id='v3-tablet-back';b.className='btn secondary tablet-return';b.dataset.action='v3-kitchen-return';b.innerHTML=icon('left')+'Volver a la tablet';main.prepend(b);}}
