 const modeAvatar=$('.mode-avatar');if(modeAvatar&&!isAdult()&&member(actor.memberId)?.photo)modeAvatar.innerHTML=mediaMarkup(member(actor.memberId).photo,member(actor.memberId).avatar,'',member(actor.memberId).name);
