async function v3Action(a,d,el,event){
 if(a.startsWith('access-')||a==='v3-account')return accessAction(a,d,el);
 if(a==='v3-kitchen-return'){closeModal();ui.kitchenActive=true;ui.view='kitchen';ui.kitchenMember=null;actor={role:'member',memberId:activeMembers().find(m=>m.role==='member')?.id||activeMembers()[0]?.id};sessionStorage.setItem(KEY+'-profile',JSON.stringify(actor));render();return true;}
 if(a==='v2-kitchen-back'){if(isAdult())nav('home');else{ui.kitchenMember=null;render();}return true;}
 if(a==='v2-kitchen-person'&&state.members.find(m=>m.id===d.id)?.role==='adult'){toast('Perfil adulto: usa el acceso adulto para gestionarlo.');return true;}
 if(a==='v3-photo-upload'||a==='v3-photo-camera'){if(needAdult())el.closest('.photo-control').querySelector(`[data-v3-photo="${a.endsWith('camera')?'camera':'upload'}"]`).click();return true;}
 if(a==='v3-photo-remove'){if(needAdult()){const p=el.closest('.photo-control');p.querySelector('input[type=hidden]').value='';p.querySelector('.photo-preview').innerHTML=mediaMarkup('',p.dataset.fallback);}return true;}
 if(!a.startsWith('v3-')&&a!=='v2-pay')return false;
 switch(a){
 case 'v3-savings-config':savingsForm(d.id);break;
 case 'v3-tier-add':if(needAdult())$('#tier-rows').insertAdjacentHTML('beforeend',tierRow({min:0,max:null,cents:0}));break;
 case 'v3-tier-remove':if(needAdult())el.closest('.tier-edit-row').remove();break;
 case 'v3-presence-member':ui.presenceMember=d.id;render();break;
 case 'v3-presence-week':ui.presenceStart=C.addDays(ui.presenceStart,Number(d.offset));render();break;
 case 'v3-presence-day':presenceException(d.id,d.date);break;
 case 'v3-presence-exception-edit':presenceException(presenceMember()?.id,C.iso(),d.id);break;
 case 'v3-presence-shift':ui.presenceStart=C.addDays(ui.presenceStart,Number(d.offset)*28);render();break;
 case 'v3-presence-form':case 'v3-presence-config':presenceForm(d.id||presenceMember()?.id);break;
 case 'v3-presence-exception':presenceException(d.member||d.id||presenceMember()?.id,d.date||C.iso());break;
 case 'v3-presence-cancel':if(needAdult())confirmDialog('Retirar esta planificaci&oacute;n','Se recalculan las tareas abiertas. No se modifica el historial cerrado.',()=>transact(s=>C.cancelPresence(s,d.id,actor),'Plan retirado.'));break;
 case 'v3-recipes-library':if(needAdult())transact(s=>C.addRecipeLibrary(s),'Ideas incorporadas sin duplicados.');break;
 case 'v3-ingredient-add':if(needAdult())$('#ingredients-editor').insertAdjacentHTML('beforeend',ingredientEditor());break;
 case 'v3-ingredient-remove':if(needAdult())el.closest('.ingredient-editor').remove();break;
 case 'v3-food-form':foodForm(d.id);break;
 case 'v2-pay':{if(!needAdult())break;const due=state.finance.dues.find(x=>x.id===d.id);if(!due)break;const q=C.allowanceQuote(state,due);confirmDialog(q.cents?'Confirmar paga':'Registrar semana sin paga',`<b>${esc(member(due.memberId).name)}</b> &middot; ${euro(q.cents)}${q.points!==null?` por ${q.points} puntos`:''}.<p>Se recalcula al confirmar. Los pagos abonados no cambian al modificar los tramos.</p>`,()=>transact(s=>C.payAllowance(s,due.id,actor),'Paga registrada.'));break;}
 default:return false;
 }return true;
}
